alter table bm_categories enable row level security;alter table bm_ingredients enable row level security;alter table bm_brands enable row level security;alter table bm_products enable row level security;alter table bm_flavor_tags enable row level security;alter table bm_ingredient_flavors enable row level security;alter table bm_product_flavors enable row level security;alter table bm_product_sources enable row level security;alter table bm_enrichment_jobs enable row level security;
revoke all on bm_categories,bm_ingredients,bm_brands,bm_products,bm_flavor_tags,bm_ingredient_flavors,bm_product_flavors,bm_product_sources,bm_enrichment_jobs from anon,authenticated;
grant select on bm_categories,bm_ingredients,bm_brands,bm_products,bm_flavor_tags,bm_ingredient_flavors,bm_product_flavors to authenticated;grant select,insert on bm_ingredients to authenticated;grant select,insert,update,delete on bm_user_bottles,bm_drinks,bm_drink_versions,bm_drink_version_ingredients to authenticated;
create policy "catalog categories read" on bm_categories for select to authenticated using(true);create policy "catalog ingredients read" on bm_ingredients for select to authenticated using(true);create policy "catalog ingredients add" on bm_ingredients for insert to authenticated with check(true);create policy "catalog brands read" on bm_brands for select to authenticated using(true);create policy "catalog products read" on bm_products for select to authenticated using(true);create policy "catalog flavors read" on bm_flavor_tags for select to authenticated using(true);create policy "ingredient flavors read" on bm_ingredient_flavors for select to authenticated using(true);create policy "product flavors read" on bm_product_flavors for select to authenticated using(true);create index if not exists bm_user_bottles_user_idx on bm_user_bottles(user_id);create index if not exists bm_drinks_user_idx on bm_drinks(user_id);